<?php 
require_once 'db.php'; require_once 'dil.php';
$conn = new mysqli($hn, $un, $pw, $db);
if (!isset($_SESSION['user_id']) || !isset($_SESSION['is_admin']) || $_SESSION['is_admin'] != 1) { header("Location: index.php"); exit; }
if (isset($_GET['action']) && $_GET['action'] == 'logout') { session_destroy(); header("Location: index.php"); exit; }
if (isset($_FILES['site_logo']) && $_FILES['site_logo']['error'] == 0) { $target_file = "logo.png"; $check = getimagesize($_FILES["site_logo"]["tmp_name"]); if($check !== false) { if (move_uploaded_file($_FILES["site_logo"]["tmp_name"], $target_file)) { header("Location: admin.php?msg=logo_updated"); } } }
if (isset($_POST['delete_user'])) { $uid = $conn->real_escape_string($_POST['user_id']); $conn->query("DELETE FROM votes_history WHERE user_id='$uid'"); $polls = $conn->query("SELECT id FROM polls WHERE created_by='$uid'"); while($p = $polls->fetch_assoc()) { $pid = $p['id']; $imgs = $conn->query("SELECT image_path FROM options WHERE poll_id='$pid'"); while($r = $imgs->fetch_assoc()){ if($r['image_path'] && file_exists($r['image_path'])) unlink($r['image_path']); } $conn->query("DELETE FROM options WHERE poll_id='$pid'"); $conn->query("DELETE FROM votes_history WHERE poll_id='$pid'"); $conn->query("DELETE FROM polls WHERE id='$pid'"); } $conn->query("DELETE FROM users WHERE id='$uid'"); header("Location: admin.php"); }
if (isset($_POST['delete_poll'])) { $pid = $conn->real_escape_string($_POST['poll_id']); $imgs = $conn->query("SELECT image_path FROM options WHERE poll_id='$pid'"); while($r = $imgs->fetch_assoc()){ if($r['image_path'] && file_exists($r['image_path'])) unlink($r['image_path']); } $conn->query("DELETE FROM votes_history WHERE poll_id='$pid'"); $conn->query("DELETE FROM options WHERE poll_id='$pid'"); $conn->query("DELETE FROM polls WHERE id='$pid'"); header("Location: admin.php"); }
?>
