<div class="container">
    <div class="navbar"><a href="index.php" class="brand"><img src="logo.png?v=<?php echo time(); ?>" alt="Logo" class="logo-img" onerror="this.style.display='none'">Admin<span style="color:var(--accent-color)">Panel</span></a><div class="d-flex gap-10 align-center"><a href="?action=logout" class="btn btn-danger"><?php echo $l['logout']; ?></a></div></div>
