    <h3 class="section-title mt-40">📊 <?php echo $l['poll_mgmt']; ?></h3>
    <div class="table-container"><table><thead><tr><th>ID</th><th><?php echo $l['poll_question']; ?></th><th>Oluşturan</th><th>Oy</th><th class="text-left"><?php echo $l['action']; ?></th></tr></thead><tbody><?php $polls = $conn->query("SELECT p.*, (SELECT COUNT(*) FROM votes_history WHERE poll_id=p.id) as votes FROM polls p ORDER BY p.id DESC"); while($p = $polls->fetch_assoc()): $creator = $p['is_anonymous'] ? $l['anonymous'] : $p['creator_name']; ?><tr><td>#<?php echo $p['id']; ?></td><td style="font-weight:600;"><?php echo $p['question']; ?></td><td><?php echo $creator; ?></td><td><?php echo $p['votes']; ?> / <?php echo $p['quota']; ?></td><td class="text-left"><form method="post" onsubmit="return confirm('<?php echo $l['del_confirm_poll']; ?>')"><input type="hidden" name="poll_id" value="<?php echo $p['id']; ?>"><button type="submit" name="delete_poll" class="btn btn-danger" style="padding:5px 12px; font-size:0.8rem;">🗑️ <?php echo $l['delete']; ?></button></form></td></tr><?php endwhile; ?></tbody></table></div>
</div>
<script>
function toggleDarkMode() { const body = document.body; const btn = document.getElementById('modeBtn'); body.classList.toggle('dark-mode'); if (body.classList.contains('dark-mode')) { localStorage.setItem('theme', 'dark'); if(btn) btn.innerHTML = "☀️"; } else { localStorage.setItem('theme', 'light'); if(btn) btn.innerHTML = "🌙"; } }
window.onload = function() { if (localStorage.getItem('theme') === 'dark') { document.body.classList.add('dark-mode'); const btn = document.getElementById('modeBtn'); if(btn) btn.innerHTML = "☀️"; } }
</script>
